def compile(self, start):
    td = deepcopy(list(self.term_defs))
    rd = [(n, p, nr_deepcopy_tree(t), o) for n, p, t, o in self.rule_defs]

    for n, (tt, pr) in td:
        if tt is None:
            continue
        ex = list(tt.find_data('expansion'))
        if len(ex) == 1 and not ex[0].children:
            raise GrammarError("Terminals cannot be empty (%s)" % n)

    tr = PrepareLiterals() * TerminalTreeToPattern()
    terms = [TerminalDef(n, tr.transform(tt), pr) for n, (tt, pr) in td if tt]

    anon = PrepareAnonTerminals(terms)
    tr = PrepareLiterals() * PrepareSymbols() * anon
    tr *= ApplyTemplates(rd)

    ebnf = EBNF_to_BNF()
    rules = []
    i = 0
    while i < len(rd):
        n, params, tree, opts = rd[i]
        i += 1
        if len(params) != 0:
            continue
        ro = RuleOptions(keep_all_tokens=True) if opts and opts.keep_all_tokens else None
        ebnf.rule_options = ro
        ebnf.prefix = n
        anon.rule_options = ro
        rules.append((n, ebnf.transform(tr.transform(tree)), opts))
    rules += ebnf.new_rules

    assert len(rules) == len({n for n, _t, _o in rules}), "Whoops, name collision"

    rtt = RuleTreeToText()
    simp = SimplifyRule_Visitor()
    cr = []
    for n, tree, opts in rules:
        simp.visit(tree)
        for i, (exp, alias) in enumerate(rtt.transform(tree)):
            if alias and n.startswith('_'):
                raise GrammarError("Rule %s is marked for expansion (it starts with an underscore) and isn't allowed to have aliases (alias=%s)" % (n, alias))
            ei = [x == _EMPTY for x in exp]
            if any(ei):
                eo = copy(opts) or RuleOptions()
                eo.empty_indices = ei
                exp = [x for x in exp if x != _EMPTY]
            else:
                eo = opts
            assert all(isinstance(x, Symbol) for x in exp), exp
            cr.append(Rule(NonTerminal(n), exp, i, alias, eo))

    if len(set(cr)) != len(cr):
        for dups in classify(cr, lambda x: x).values():
            if len(dups) > 1:
                if dups[0].expansion:
                    raise GrammarError("Rules defined twice: %s\n\n(Might happen due to colliding expansion of optionals: [] or ?)"
                                       % ''.join('\n  * %s' % i for i in dups))
                assert len({(r.alias, r.order, r.options) for r in dups}) == len(dups)
        cr = list(set(cr))

    while True:
        c = len(cr)
        used = {s for r in cr for s in r.expansion if isinstance(s, NonTerminal) and s != r.origin}
        used |= {NonTerminal(s) for s in start}
        cr, unused = classify_bool(cr, lambda r: r.origin in used)
        for r in unused:
            logger.debug("Unused rule: %s", r)
        if len(cr) == c:
            break

    used = {t.name for r in cr for t in r.expansion if isinstance(t, Terminal)}
    terms, unused = classify_bool(terms, lambda t: t.name in used or t.name in self.ignore)
    if unused:
        logger.debug("Unused terminals: %s", [t.name for t in unused])

    return terms, cr, self.ignore
```

