def visit(self, root):
    v, p, s = set(), [], deque([root])
    pno, pni = self.visit_packed_node_out, self.visit_packed_node_in
    sno, sni = self.visit_symbol_node_out, self.visit_symbol_node_in
    ino = getattr(self, 'visit_intermediate_node_out', sno)
    ini = getattr(self, 'visit_intermediate_node_in', sni)
    vtn, oc = self.visit_token_node, self.on_cycle

    while s:
        c = next(reversed(s))
        try:
            n = next(c)
        except StopIteration:
            s.pop()
            continue
        except TypeError:
            pass
        else:
            if n is None:
                continue
            if id(n) in v:
                oc(n, p)
                continue
            s.append(n)
            continue

        if not isinstance(c, ForestNode):
            vtn(c)
            s.pop()
            continue

        i = id(c)
        if i in v:
            (pno if isinstance(c, PackedNode) else ino if c.is_intermediate else sno)(c)
            s.pop()
            p.pop()
            v.remove(i)
            continue

        v.add(i)
        p.append(c)
        n = pni(c) if isinstance(c, PackedNode) else ini(c) if c.is_intermediate else sni(c)
        if n is None:
            continue
        if not isinstance(n, ForestNode) and not isinstance(n, Token):
            n = iter(n)
        elif id(n) in v:
            oc(n, p)
            continue
        s.append(n)
```
